    #[test]
    fn continuation_is_emitted_only_for_in_progress_work() {
        let in_progress = continuation_test_work(WorkPhase::Active, WorkCondition::Normal, None);
        assert!(is_active_work_continuation_candidate(
            &in_progress,
            "member-run-test",
            std::slice::from_ref(&in_progress),
        ));

        for (label, phase, condition, resolution) in [
            ("open", WorkPhase::Open, WorkCondition::Normal, None),
            ("blocked", WorkPhase::Active, WorkCondition::Blocked, None),
            ("on_hold", WorkPhase::Active, WorkCondition::OnHold, None),
            ("review", WorkPhase::Review, WorkCondition::Normal, None),
            (
                "accepted",
                WorkPhase::Closed,
                WorkCondition::Normal,
                Some(WorkResolution::Accepted),
            ),
            (
                "cancelled",
                WorkPhase::Closed,
                WorkCondition::Normal,
                Some(WorkResolution::Cancelled),
            ),
        ] {
            let work = continuation_test_work(phase, condition, resolution);
            assert!(
                !is_active_work_continuation_candidate(
                    &work,
                    "member-run-test",
                    std::slice::from_ref(&work),
                ),
                "{label} Work must not receive active continuation",
            );
        }
    }

    #[cfg(unix)]
    fn process_exists(pid: u32) -> bool {
        unsafe { libc::kill(pid as libc::pid_t, 0) == 0 }
    }

    #[cfg(unix)]
    fn process_group_command(script: &str) -> Command {
        let mut command = Command::new("sh");
        command.arg("-c").arg(script);
        isolate_provider_child_process_group(&mut command);
        command
    }

    #[cfg(unix)]
    #[test]
    fn claude_runner_guard_kills_stale_active_process_group() {
        let marker = std::env::temp_dir().join(format!(
            "harness-provider-child-group-{}-{}",
            std::process::id(),
            current_unix_ms()
        ));
        let mut command = process_group_command(r#"sleep 30 & echo $! > "$1"; wait"#);
        command.arg("provider-child-test").arg(&marker);
        let child = command.spawn().expect("spawn provider child group");
        let leader_pid = child.id();
        let guard = ProviderChildGuard::new(child);
        let deadline = Instant::now() + Duration::from_secs(2);
        let descendant_pid = loop {
            if let Ok(pid) = fs::read_to_string(&marker) {
                if let Ok(pid) = pid.trim().parse::<u32>() {
                    break pid;
                }
            }
            assert!(
                Instant::now() < deadline,
                "descendant pid marker was not populated"
            );
            std::thread::sleep(Duration::from_millis(10));
        };

        drop(guard);

        assert!(
            !process_exists(leader_pid),
            "group leader survived guard drop"
        );
        let deadline = Instant::now() + Duration::from_secs(2);
        while process_exists(descendant_pid) && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(10));
        }
        assert!(
            !process_exists(descendant_pid),
            "provider descendant survived stale guard teardown"
        );
        let _ = fs::remove_file(marker);
    }

    #[cfg(unix)]
    #[test]
    fn claude_runner_guard_disarms_after_normal_completion() {
        let child = process_group_command("exit 0")
            .spawn()
            .expect("spawn normally completing provider child");
        let pid = child.id();
        let mut guard = ProviderChildGuard::new(child);

        let status = guard.wait_and_disarm().expect("normal provider wait");

        assert!(status.success());
        assert!(!guard.armed, "normal wait must disarm teardown");
        drop(guard);
        assert!(
            !process_exists(pid),
            "normally reaped provider child survived"
        );
    }

