    #[test]
    fn close_without_live_supervisor_requires_runtime_command_recovery_without_side_effects() {
        // A missing Supervisor does not prove the provider effect is absent.
        // The lifecycle API must not invent a second stop authority by reaping
        // a Running projection outside the RuntimeCommand ledger.
        let (store, root) = temp_store("durable-close-reap");
        let created = create_two_member_team_run(&store);
        let initial_run = created.team_run;
        let mut run = initial_run.clone();
        run.status = TeamRunStatus::Running;
        run.updated_at = "unix-ms:2".into();
        store
            .compare_and_append_team_run_lifecycle(&initial_run, &run)
            .expect("mark run running");
        let initial_member = created.member_runs[0].clone();
        let mut member = initial_member.clone();
        member.status = MemberRunStatus::Running;
        member.last_event_at = Some("unix-ms:2".into());
        store
            .compare_and_append_member_run(&initial_member, &member)
            .expect("mark member running");

        let member_rows_before = store.member_runs().expect("member rows before");
        let close_rows_before = store
            .team_member_close_requests()
            .expect("close rows before");
        let error = close_team_member_value(
            &store,
            &run.id,
            &member.id,
            &serde_json::json!({
                "requested_by": "host",
                "reason": "lane accepted"
            }),
        )
        .expect_err("ambiguous runtime must require recovery");
        assert!(error
            .to_string()
            .contains("RUNTIME_COMMAND_RECOVERY_REQUIRED"));
        assert_eq!(
            store.member_runs().expect("member rows after"),
            member_rows_before
        );
        assert_eq!(
            store
                .team_member_close_requests()
                .expect("close rows after"),
            close_rows_before
        );
        let _ = std::fs::remove_dir_all(root);
    }

    #[cfg(any())] // Historical CLI-send/manual-ack authority; canonical MessageDelivery journey supersedes it.
    fn member_to_host_is_delivered_manual_ack_but_member_mail_stays_queued() {
        let (store, root) = temp_store("team-delivery-routing");
        let created = create_two_member_team_run(&store);
        let first = &created.member_runs[0];
        let second = &created.member_runs[1];
        let seed = seed_host_conversation(&store, &created, 0);
        let correlation = seed.correlation_id.clone();

        let host_mail = send_team_message(
            &store,
            &created.team_run.id,
            &first.id,
            vec!["host".into()],
            ProviderDispatchIntent::Message,
            "Need a product decision",
            Some(correlation.clone()),
            Some(seed.id.clone()),
            None,
            None,
        )
        .expect("member to host");
        assert_eq!(
            host_mail.deliveries[0].policy,
            TeamDeliveryPolicy::ManualAck
        );
        assert_eq!(
            host_mail.deliveries[0].status,
            TeamDeliveryStatus::Delivered
        );
        assert_eq!(host_mail.deliveries[0].attempt, 1);

        let peer_mail = send_team_message(
            &store,
            &created.team_run.id,
            &first.id,
            vec![second.id.clone()],
            ProviderDispatchIntent::Message,
            "Shared interface is ready",
            Some(correlation.clone()),
            None,
            None,
            None,
        )
        .expect("member to peer");
        assert_eq!(peer_mail.deliveries[0].policy, TeamDeliveryPolicy::Queue);
        assert_eq!(peer_mail.deliveries[0].status, TeamDeliveryStatus::Queued);
        assert_eq!(peer_mail.deliveries[0].attempt, 0);

        let host_to_member = send_team_message(
            &store,
            &created.team_run.id,
            "host",
            vec![first.id.clone()],
            ProviderDispatchIntent::Message,
            "Use the stable interface",
            Some(correlation),
            Some(host_mail.id),
            None,
            None,
        )
        .expect("host to member");
        assert_eq!(
            host_to_member.deliveries[0].policy,
            TeamDeliveryPolicy::Queue
        );
        assert_eq!(
            host_to_member.deliveries[0].status,
            TeamDeliveryStatus::Queued
        );
        let _ = std::fs::remove_dir_all(root);
    }

    #[cfg(any())] // Historical CLI-send planning conversation; canonical RoleAction messaging is covered store-live.
    fn member_planning_is_ordinary_correlated_conversation() {
        let (store, root) = temp_store("member-plan-conversation");
        let created = create_two_member_team_run(&store);
        let member = &created.member_runs[0];
        let assignment = seed_host_conversation(&store, &created, 0);

        let request = send_team_message(
            &store,
            &created.team_run.id,
            "host",
            vec![member.id.clone()],
            ProviderDispatchIntent::Message,
            "Return a Markdown plan before implementation. Do not execute yet.",
            Some(assignment.correlation_id.clone()),
            Some(assignment.id.clone()),
            None,
            None,
        )
        .expect("Host requests plan");
        let proposal_one = send_team_message(
            &store,
            &created.team_run.id,
            &member.id,
            vec!["host".into()],
            ProviderDispatchIntent::Message,
            "1. Inspect\n2. Implement\n3. Verify",
            Some(assignment.correlation_id.clone()),
            Some(request.id.clone()),
            None,
            None,
        )
        .expect("owner proposes");
        let feedback = send_team_message(
            &store,
            &created.team_run.id,
            "host",
            vec![member.id.clone()],
            ProviderDispatchIntent::Message,
            "Add rollback and integration checks",
            Some(assignment.correlation_id.clone()),
            Some(proposal_one.id.clone()),
            None,
            None,
        )
        .expect("Host challenges proposal");

        let proposal_two = send_team_message(
            &store,
            &created.team_run.id,
            &member.id,
            vec!["host".into()],
            ProviderDispatchIntent::Message,
            "1. Inspect\n2. Implement\n3. Integrate\n4. Roll back if checks fail",
            Some(assignment.correlation_id.clone()),
            Some(feedback.id),
            None,
            None,
        )
        .expect("owner revises");
        send_team_message(
            &store,
            &created.team_run.id,
            "host",
            vec![member.id.clone()],
            ProviderDispatchIntent::Message,
            "Plan reviewed. Execute revision 2.",
            Some(assignment.correlation_id.clone()),
            Some(proposal_two.id),
            None,
            None,
        )
        .expect("Host instructs execution");
        let _ = std::fs::remove_dir_all(root);
    }

    #[cfg(any())] // Historical host-inbox fixture authored through retired TeamMessageProjection.
    fn host_inbox_is_scoped_to_exact_native_thread_binding() {
        let (store, root) = temp_store("host-native-inbox");
        let created = create_two_member_team_run(&store);
        let member = &created.member_runs[0];
        let assignment = seed_host_conversation(&store, &created, 0);
        let current = latest_team_run(&store, &created.team_run.id).expect("current run");
        let mut bound = current.clone();
        bound.host_surface = "codex-app".into();
        bound.host_thread_id = Some("codex-thread-a".into());
        bound.updated_at = "unix-ms:host-bound".into();
        store
            .compare_and_append_team_run(&current, &bound)
            .expect("bind native Host");

        let mail = send_team_message(
            &store,
            &bound.id,
            &member.id,
            vec!["host".into()],
            ProviderDispatchIntent::Message,
            "QUESTION: choose interface A or B",
            Some(assignment.correlation_id.clone()),
            Some(assignment.id.clone()),
            None,
            None,
        )
        .expect("member asks Host");

        let exact = host_inbox_for_native_thread(&store, "codex-app", "codex-thread-a", false)
            .expect("exact Host inbox");
        assert_eq!(exact.len(), 1);
        assert_eq!(exact[0]["team_run_id"], bound.id);
        assert_eq!(exact[0]["messages"][0]["id"], mail.id);
        assert!(
            host_inbox_for_native_thread(&store, "codex-app", "another-thread", false,)
                .expect("other Host inbox")
                .is_empty(),
            "one native Host task must never receive another task's mail"
        );
        assert!(
            host_inbox_for_native_thread(&store, "claude-code", "codex-thread-a", false)
                .expect("other surface")
                .is_empty()
        );
        let _ = std::fs::remove_dir_all(root);
    }

